import java.util.*;
abstract class Question{int marks;Question(int m){marks=m;}abstract boolean checkAnswer(String a);}class MCQ extends Question{String correct;MCQ(int m,String c){super(m);correct=c;}boolean checkAnswer(String a){return correct.equalsIgnoreCase(a);}}class TrueFalseQuestion extends Question{String correct;TrueFalseQuestion(int m,String c){super(m);correct=c;}boolean checkAnswer(String a){return correct.equalsIgnoreCase(a);}}
class Attempt{Map<Question,String> answers=new LinkedHashMap<>();boolean submitted=false;void answer(Question q,String a){if(submitted){System.out.println("Cannot change submitted answers");return;}answers.put(q,a);System.out.println("Answer recorded");}void submit(){if(submitted)return;submitted=true;int score=0,total=0;for(Question q:answers.keySet()){total+=q.marks;if(q.checkAnswer(answers.get(q)))score+=q.marks;}System.out.println("Total score: "+score+"/"+total);}}
public class OnlineExaminationSystem{public static void main(String[] args){Question q1=new MCQ(5,"C"),q2=new TrueFalseQuestion(5,"False");Attempt a=new Attempt();System.out.println("Exam started");a.answer(q1,"C");a.answer(q2,"True");a.submit();a.answer(q1,"A");}}